// Searchable catalog of EPSG/ESRI coordinate systems (from PROJ's proj.db,
// regenerated by scripts/build-crs-list.sh).

export interface CrsEntry {
  id: string;
  name: string;
  projected: boolean;
  area: string;
  bounds: [number, number, number, number] | null;
}

type Row = [string, string, "p" | "g", string, number | null, number | null, number | null, number | null];

let catalog: CrsEntry[] | null = null;

export async function loadCatalog(): Promise<CrsEntry[]> {
  if (catalog) return catalog;
  const rows = (await import("./crs-list.json")).default as unknown as Row[];
  catalog = rows.map(([id, name, t, area, w, s, e, n]) => ({
    id,
    name,
    projected: t === "p",
    area,
    bounds: w === null || s === null || e === null || n === null ? null : [w, s, e, n],
  }));
  return catalog;
}

export function crsName(id: string): string {
  return catalog?.find((c) => c.id.toUpperCase() === id.toUpperCase())?.name ?? id;
}

export const FAVORITES = ["EPSG:4326", "EPSG:4269", "EPSG:3857", "EPSG:5070", "EPSG:4267"];

/** Rank catalog entries for a query; optionally only those covering a point. */
export function searchCatalog(
  list: CrsEntry[],
  query: string,
  opts: { kind?: "all" | "projected" | "geographic"; at?: [number, number] | null; limit?: number } = {},
): CrsEntry[] {
  const q = query.trim().toLowerCase();
  const terms = q.split(/\s+/).filter(Boolean);
  const { kind = "all", at = null, limit = 300 } = opts;
  const out: { e: CrsEntry; score: number }[] = [];
  for (const e of list) {
    if (kind === "projected" && !e.projected) continue;
    if (kind === "geographic" && e.projected) continue;
    if (at && e.bounds) {
      const [w, s, ea, n] = e.bounds;
      const lon = at[0];
      const inLon = w <= ea ? lon >= w && lon <= ea : lon >= w || lon <= ea; // antimeridian
      if (!inLon || at[1] < s || at[1] > n) continue;
    }
    const hay = `${e.id} ${e.name} ${e.area}`.toLowerCase();
    if (!terms.every((t) => hay.includes(t))) continue;
    let score = 0;
    if (q && e.id.toLowerCase() === q) score += 1000;
    if (q && (e.id.toLowerCase().endsWith(`:${q}`) || e.id.toLowerCase() === `epsg:${q}`)) score += 900;
    if (q && e.name.toLowerCase().startsWith(q)) score += 50;
    if (FAVORITES.includes(e.id)) score += 30;
    if (e.id.startsWith("EPSG")) score += 10;
    // Prefer regional systems over world-wide ones when filtering by location.
    if (at && e.bounds) score -= Math.min(20, ((e.bounds[2] - e.bounds[0]) * (e.bounds[3] - e.bounds[1])) / 3000);
    out.push({ e, score });
  }
  out.sort((a, b) => b.score - a.score);
  return out.slice(0, limit).map((x) => x.e);
}

/** WGS 84 / UTM zone code for a lon/lat (mirrors the engine's choice). */
export function utmFor(lon: number, lat: number, datum: "WGS84" | "NAD83" = "WGS84"): string {
  const zone = Math.min(60, Math.max(1, Math.floor((lon + 180) / 6) + 1));
  if (datum === "NAD83" && lat >= 0 && zone >= 1 && zone <= 23) return `EPSG:${26900 + zone}`;
  return `EPSG:${(lat >= 0 ? 32600 : 32700) + zone}`;
}
